/// <summary>
/// MPJ_24248 Price Data Extract
/// </summary>
final class METPriceSimulatorAutoCharges2_test
{
}

Method.Source:
public static void main(Args args)
{
    METPriceSimulatorAutoCharges2_test instance = new METPriceSimulatorAutoCharges2_test();
    
    try
    {
        instance.run2();
    }
    catch
    {
        error("@MET:METError");
    }
    info("@MET:METJubii2");
}

    public void run2()
    {
        InventDim inventDim;
        inventDim.clear();
        inventDim.InventSiteId = "@MET:CnFood";

        inventDim = inventDim::findOrCreate(inventDim);

        SalesLine   salesLineStd = SalesLine::find("@MET:SO0006", 1);
        SalesTable  salesTableStd = SalesTable::find("@MET:SO0006");

        SalesLine   salesLineTmp;
        SalesTable  salesTableTmp;
        
        /*
        salesLineTmp.setTmp();
        salesTableTmp.setTmp();
        */

        buf2Buf(salesTableStd, salesTableTmp);
        buf2Buf(salesLineStd, salesLineTmp);

        salesTableTmp.SalesId       = guid2Str(newGuid()); //dont consume genuine salesId from Number seq as this is only a temp record.
        //salesTableTmp.doInsert();

        salesLineTmp.salesId    = salesTableTmp.SalesId;
        salesLineTmp.InventTransId = guid2Str(newGuid()); //dont consume genuine InventTransId from Number seq as this is only a temp record.
        //salesLineTmp.doInsert();

        InventTable inventTable;

        inventTable = salesLineTmp.inventTable();

        MarkupTransInsertParameters parameters = MarkupTransInsertParameters::construct();

        parameters.ModuleCategory   = HeadingLine::Line;
        parameters.ModuleType       = MarkupModuleType::Cust;
        parameters.Source           = salesLineTmp;
        parameters.Account          = salesTableTmp.markupCustomerAccount();
        parameters.AccountGroup     = salesTableTmp.MarkupGroup;
        parameters.Currency         = salesTableTmp.CurrencyCode;
        parameters.LanguageId       = salesTableTmp.LanguageId;
        parameters.Item             = salesLineTmp.itemId;
        parameters.InventSiteId     = inventDim.InventSiteId;
        parameters.InventLocationId = inventDim.InventLocationId;
        parameters.ItemGroup        = inventTable.salesMarkupGroup();
        parameters.InvertSign       = false;
        parameters.DeleteExistingMarkupTrans = true;
        parameters.DlvModeId        = salesLineTmp.dlvMode;
        parameters.DlvModeGroup     = DlvMode::find(salesLineTmp.DlvMode).MarkupGroup;
        parameters.TotalAmount      = salesLineTmp.LineAmount;
        parameters.McrReturnMarkup  = false;
        
        List matchedAutoChargeLineRecIdList = METPriceSimulatorAutoCharges2_test::metFindAllMatchedAutoChargesLines(parameters, salesTableTmp);

        ListEnumerator enumerator = matchedAutoChargeLineRecIdList.getEnumerator();
        MarkupAutoLine markupAutoLine;
        while (enumerator.moveNext())
        {
            markupAutoLine = METPriceSimulatorAutoCharges2_test::metFindMarkupAutoLineByRecId(str2int64(enumerator.current()));
            this.insertForMarkupAutoLine(markupAutoLine, salesLineTmp, parameters);
        }

    }

    public void run()
    {
        InventDim inventDim;
        inventDim.clear();
        inventDim.InventSiteId = "@MET:CnFood";

        inventDim = inventDim::findOrCreate(inventDim);

        SalesLine   salesLineTmp;
        SalesTable  salesTableTmp;
        
        salesLineTmp.setTmp();
        salesTableTmp.setTmp();

        salesTableTmp.clear();
        salesTableTmp.initValue();
        salesTableTmp.SalesId       = guid2Str(newGuid()); //dont consume genuine salesId from Number seq as this is only a temp record.
        salesTableTmp.CustAccount   = "@MET:AC6413";
        salesTableTmp.initFromCustTable();
        salesTableTmp.CurrencyCode  = "@MET:CurrncyCod";
        salesTableTmp.doInsert();

        salesLineTmp.clear();
        salesLineTmp.salesId    = salesTableTmp.SalesId;
        salesLineTmp.ItemId     = "@MET:Item154";
        
        salesLineTmp.initFromSalesTable(salesTableTmp, false);
        salesLineTmp.initLineFromItemOrCategory();
        salesLineTmp.InventDimId = inventDim.InventDimId;
        salesLineTmp.SalesQty    = 1;
        salesLineTmp.LineAmount  = 10;
        salesLineTmp.salesPrice  = salesLineTmp.LineAmount / salesLineTmp.SalesQty;
        salesLineTmp.InventTransId = guid2Str(newGuid()); //dont consume genuine InventTransId from Number seq as this is only a temp record.

        salesLineTmp.doInsert();

        InventTable inventTable;

        inventTable = salesLineTmp.inventTable();

        MarkupTransInsertParameters parameters = MarkupTransInsertParameters::construct();

        parameters.ModuleCategory   = HeadingLine::Line;
        parameters.ModuleType       = MarkupModuleType::Cust;
        parameters.Source           = salesLineTmp;
        parameters.Account          = salesTableTmp.markupCustomerAccount();
        parameters.AccountGroup     = salesTableTmp.MarkupGroup;
        parameters.Currency         = salesTableTmp.CurrencyCode;
        parameters.LanguageId       = salesTableTmp.LanguageId;
        parameters.Item             = salesLineTmp.itemId;
        parameters.InventSiteId     = inventDim.InventSiteId;
        parameters.InventLocationId = inventDim.InventLocationId;
        parameters.ItemGroup        = inventTable.salesMarkupGroup();
        parameters.InvertSign       = false;
        parameters.DeleteExistingMarkupTrans = true;
        parameters.DlvModeId        = salesLineTmp.dlvMode;
        parameters.DlvModeGroup     = DlvMode::find(salesLineTmp.DlvMode).MarkupGroup;
        parameters.TotalAmount      = salesLineTmp.LineAmount;
        parameters.McrReturnMarkup  = false;
        
        List matchedAutoChargeLineRecIdList = METPriceSimulatorAutoCharges2_test::metFindAllMatchedAutoChargesLines(parameters, salesTableTmp);

        ListEnumerator enumerator = matchedAutoChargeLineRecIdList.getEnumerator();
        MarkupAutoLine markupAutoLine;
        while (enumerator.moveNext())
        {
            markupAutoLine = METPriceSimulatorAutoCharges2_test::metFindMarkupAutoLineByRecId(str2int64(enumerator.current()));
            this.insertForMarkupAutoLine(markupAutoLine, salesLineTmp, parameters);
        }

    }

public void insertForMarkupAutoLine(MarkupAutoLine _markupAutoLine, Common _parent, MarkupTransInsertParameters _parameters)
{
    MarkupTrans markuptrans = this.initializeMarkupTransFromParent(_markupAutoLine, _parent, _parameters);
    markuptrans.insert();
}

    static public List metFindAllMatchedAutoChargesLines(MarkupTransInsertParameters _parameters, SalesTable _salesTable)
    {
        List matchedMarkupAutoLine = new List(Types::String);
        CLRObject autoChargeEntities = GUPMatchingEntityHelper::createCLRList(new GUPMatchingEntityAutoCharge());

        Microsoft.Dynamics.Commerce.Runtime.DataModel.UnifiedPricingParameter unifiedPricingParameter = new Microsoft.Dynamics.Commerce.Runtime.DataModel.UnifiedPricingParameter();

        if (_parameters.ModuleCategory == HeadingLine::Line)
        {
            MarkupAutoLine markupAutoLine;
            MarkupAutoTable markupAutoTable;
            GUPPriceComponentCodeSetup priceComponentCodeSetup;
            SalesLine salesLine = _parameters.Source;
            InventTransId inventTransId = salesLine.InventTransId;

            if (salesLine.IsFreeItemLine == NoYes::Yes || !inventTransId)
            {
                return matchedMarkupAutoLine;
            }

            while select markupAutoLine
                exists join markupAutoTable
                where markupAutoTable.ModuleType == MarkupModuleType::Cust
                    && markupAutoTable.ModuleCategory == HeadingLine::Line
                    && markupAutoTable.IsGupMarkupAuto == NoYes::Yes
                    && markupAutoLine.TableRecId == markupAutoTable.RecId
                exists join priceComponentCodeSetup
                order by priceComponentCodeSetup.CalculationSequence
                where markupAutoTable.PriceComponentCodeName == priceComponentCodeSetup.PriceComponentCodeName
                    && priceComponentCodeSetup.PricingTreeName == ''
            {
                GUPMatchingEntityAutoCharge matchEntityAutoCharge = new GUPMatchingEntityAutoCharge();
                matchEntityAutoCharge.initFromMarkupAutoLine(markupAutoLine);
                autoChargeEntities.add(matchEntityAutoCharge);
            }

            if (autoChargeEntities.get_Count())
            {
                //SalesTable salesTable = SalesTable::find(salesLine.SalesId);

                CLRObject salesLineIdSet = GUPMatchingEntityHelper::createCLRStringSet();
                salesLineIdSet.add(inventTransId);

                Microsoft.Dynamics.Commerce.Runtime.DataModel.SalesTransaction salesTransaction = RetailPricingEngineHelper::getSalesTransactionFromOrder(_salesTable, salesLine);
                salesTransaction.SalesId = _salesTable.SalesId;

                var result = Microsoft.Dynamics.Commerce.Runtime.Services.PricingEngine.AttributePricingPropertiesMatcher::GetMasterDataMatchedByTransaction(salesTransaction,
                                                                                                                                                                GUPMatchingEntityHelper::initializeDataAcessor(_salesTable.SalesId),
                                                                                                                                                                unifiedPricingParameter,
                                                                                                                                                                autoChargeEntities,
                                                                                                                                                                salesLineIdSet);

                var listEnumerator = result.get_Item(inventTransId).GetEnumerator();
                while(listEnumerator.moveNext())
                {
                    matchedMarkupAutoLine.addEnd(listEnumerator.get_Current().id);
                }
            }
        }
        return matchedMarkupAutoLine;
    }

    public static MarkupAutoLine metFindMarkupAutoLineByRecId(RecId _recId, boolean _update = false)
    {
        MarkupAutoLine found;

        select firstonly found
            where found.recId == _recId;

        if (_update)
        {
            found.selectForUpdate(true);
        }

        return found;
    }

    public MarkupTrans initializeMarkupTransFromParent(MarkupAutoLine _markupAutoLine, Common parent, MarkupTransInsertParameters _parameters)
    {
        MarkupTrans markupTrans;
        markupTrans.initFromMarkupTable(_markupAutoLine.markupTable());
        markupTrans.initFromMarkupAutoLine(_markupAutoLine);
        //markupTrans.initSequenceCompoundSpecificUoMFromMarkupAutoLine(_markupAutoLine, parent);
        markupTrans.initFromCaller(parent.TableId, parent);
        markupTrans.MCRInstallmentEligible = false;

        if (_markupAutoLine.MarkupCurrencyCode)
        {
            markupTrans.CurrencyCode = _markupAutoLine.MarkupCurrencyCode;
        }

        markupTrans.TransTableId   = parent.TableId;
        markupTrans.TransRecId     = parent.RecId;
        markupTrans.LineNum        = MarkupTrans::lastLineNum(parent.TableId, parent.RecId) + 1;

        if (_parameters.ModuleType == MarkupModuleType::Delivery)
        {
            markupTrans.ModuleType = MarkupModuleType::Delivery;
        }

        if (_parameters.invertSign &&
            markupTrans.MarkupCategory == MarkupCategory::Fixed)
        {
            markupTrans.Value = -markupTrans.Value;
        }

        if (_parameters.LanguageId)
        {
            markupTrans.Txt = LanguageTxt::languageId(tableNum(MarkupAutoTable), _markupAutoLine.RecId, _parameters.LanguageId);
        }

        if (!markupTrans.Txt)
        {
            markupTrans.Txt = MarkupTable::find(_markupAutoLine.ModuleType, _markupAutoLine.MarkupCode).Txt;
        }

        markupTrans.IsAutoCharge = NoYes::Yes;
        
        return markupTrans;
    }
